// CompareLabeling is the generated lifecycle comparison boundary. Pass stored snapshots and the effective assignment draft; its values are not transformed or compared to the result. Both snapshots, when present, must have the same primary key. This function performs no database work or automatic capture.
func CompareLabeling(before, after foundryvalue.Optional[Labeling], assigned LabelingDraft) (LabelingChanges, error) {
	before = foundryLabelingSnapshot(before)
	after = foundryLabelingSnapshot(after)
	var changes LabelingChanges
	var err error
	changes.fields.ID, err = lifecycle.CompareModelField(codec.ID[Labeling](), before, after, assigned.fieldID.IsSet(), func(item Labeling) model.ID[Labeling] { return item.ID })
	if err != nil {
		return LabelingChanges{}, fmt.Errorf("compare Labeling.ID: %w", err)
	}
	if before.IsSet() && after.IsSet() && (changes.fields.ID.Changed() || changes.fields.ID.Assigned()) {
		return LabelingChanges{}, foundryfault.New(foundryfault.Invalid, "model change cannot replace or assign its existing primary key")
	}
	changes.fields.LabelID, err = lifecycle.CompareModelField(codec.ID[Label](), before, after, assigned.fieldLabelID.IsSet(), func(item Labeling) model.ID[Label] { return item.LabelID })
	if err != nil {
		return LabelingChanges{}, fmt.Errorf("compare Labeling.LabelID: %w", err)
	}
	changes.fields.LabelableType, err = lifecycle.CompareModelField(codec.String[foundryquery.MorphName](), before, after, assigned.fieldLabelableType.IsSet(), func(item Labeling) foundryquery.MorphName { return item.LabelableType })
	if err != nil {
		return LabelingChanges{}, fmt.Errorf("compare Labeling.LabelableType: %w", err)
	}
	changes.fields.LabelableID, err = lifecycle.CompareModelField(codec.String[string](), before, after, assigned.fieldLabelableID.IsSet(), func(item Labeling) string { return item.LabelableID })
	if err != nil {
		return LabelingChanges{}, fmt.Errorf("compare Labeling.LabelableID: %w", err)
	}
	changes.before = before
	changes.after = after
	return changes, nil
}
