// LabelingRetrievalHooks declares complete-model read callbacks. Reference a local factory with retrieval=Factory on the model directive. The stored model is a read-only value; getters remain explicit.
type LabelingRetrievalHooks struct {
	// Retrieved runs after successful stored hydration and row closure. The executor retains the caller's capability and wrappers; no write transaction is created implicitly. Return an error to stop this read. Nil is skipped.
	Retrieved func(context.Context, database.Executor, Labeling) error
}

// LabelingRetrievalObserver retains this model's concrete retrieval factory type. Names share the selected database's write/retrieval namespace.
type LabelingRetrievalObserver = lifecycle.Observer[Labeling, LabelingRetrievalHooks]

// NewLabelingRetrievalObserver declares a typed retrieval observer without registering or constructing hooks.
func NewLabelingRetrievalObserver(observer string) LabelingRetrievalObserver {
	return lifecycle.NewRetrievalObserver[Labeling, LabelingRetrievalHooks](observer)
}

// RegisterLabelingRetrievalObserver binds dependency construction to a database module. Its factory runs once per nonempty complete fetch/batch and selected model role; write hydration, DTOs and scalar reads skip it.
func RegisterLabelingRetrievalObserver(registrar *foundation.Registrar, pool foundation.Key[*database.DB], observer LabelingRetrievalObserver, construct func(foundation.Resolver) (func() LabelingRetrievalHooks, error)) error {
	return database.RegisterObserver(registrar, pool, observer, construct)
}
func (LabelingRetrievalHooks) foundryRetrievalHooks(ctx context.Context, observerSet lifecycle.Observers) (foundryquery.RetrievalHooks[Labeling], error) {
	factories, err := lifecycle.RetrievalObserverFactories[Labeling, LabelingRetrievalHooks](observerSet)
	if err != nil {
		return foundryquery.RetrievalHooks[Labeling]{}, err
	}
	var allHooks []LabelingRetrievalHooks
	if err := ctx.Err(); err != nil {
		return foundryquery.RetrievalHooks[Labeling]{}, err
	}
	for _, factory := range factories {
		if err := ctx.Err(); err != nil {
			return foundryquery.RetrievalHooks[Labeling]{}, err
		}
		allHooks = append(allHooks, factory())
	}
	if err := ctx.Err(); err != nil {
		return foundryquery.RetrievalHooks[Labeling]{}, err
	}
	return foundryquery.RetrievalHooks[Labeling]{Retrieved: func(ctx context.Context, executor database.Executor, item Labeling) error {
		for _, hooks := range allHooks {
			if err := ctx.Err(); err != nil {
				return err
			}
			if hooks.Retrieved != nil {
				if err := hooks.Retrieved(ctx, executor, item); err != nil {
					return err
				}
			}
		}
		return ctx.Err()
	}}, nil
}

